let index=-1,step=0,rotation=0,tilt=.02,pointer=null,lastTap=-1000,flash=0,action=null,queued=0;let turns=0,holding=false,holdTimer=null,previewMode=false,lastSaved=null;const previewCache=new Map();let finale=null,assignmentLoading=false,makerId=null,autoBuild=false,boostUntil=0,lastSqueak=0,zoom=1,danceMode=-1,danceStarted=0,pinchState=null;const touches=new Map(),danceNames=['Bounce','Shuffle','Twist','Robot','Headbang','Wiggle','Twerk'];
