function material(c,variant=0){return appearanceMaterial(c,variant)}
function makePart(p,i,variant=0){const group=new THREE.Group(),mat=material(p.c,variant);if(p.points){const curve=new THREE.CatmullRomCurve3(p.points.map(v=>new THREE.Vector3(...v)),false,'centripetal');const tube=new THREE.Mesh(new THREE.TubeGeometry(curve,Math.max(30,p.points.length*7),p.r,12,false),mat);group.add(tube);for(const pos of [p.points[0],p.points.at(-1)]){const end=new THREE.Mesh(new THREE.SphereGeometry(p.r,16,12),mat);end.position.set(...pos);group.add(end)}}else if(p.a){const a=new THREE.Vector3(...p.a),b=new THREE.Vector3(...p.b),m=new THREE.Mesh((previewMode?new THREE.SphereGeometry(1,22,16):appearanceGeometry(i,variant)),mat);m.position.copy(a).add(b).multiplyScalar(.5);m.scale.set(p.r,a.distanceTo(b)/2+p.r*.7,p.r);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),b.sub(a).normalize());group.add(m)}else{const m=new THREE.Mesh((previewMode?new THREE.SphereGeometry(1,22,16):appearanceGeometry(i,variant)),mat);m.position.set(...p.p);m.scale.set(...p.s);group.add(m)}group.userData.anchor=new THREE.Box3().setFromObject(group).getCenter(new THREE.Vector3());return group}
