function disposeModel(o){if(!o)return;const geometries=new Set();o.traverse(m=>{if(m.geometry)geometries.add(m.geometry)});geometries.forEach(g=>g.dispose());}

function surprise(chosen){let n;if(Number.isInteger(chosen))n=chosen;else{do{n=Math.floor(Math.random()*characters.length)}while(n===index)}index=n;zoom=1;danceMode=-1;touches.clear();pinchState=null;finale?.clear();autoBuild=false;boostUntil=0;const c=characters[index];step=0;action=null;queued=0;holding=false;clearTimeout(holdTimer);lastSaved=null;rotation=c.angle;tilt=.02;pointer=null;lastTap=-1000;document.documentElement.style.setProperty('--accent','#9bff43');if(model){scene.remove(model);disposeModel(model);face.userData.resources.forEach(m=>m.dispose())}const built=makeCharacter(c);model=built.group;parts=built.pieces;face=built.face;scene.add(model);const box=new THREE.Box3().setFromObject(model);fit={size:box.getSize(new THREE.Vector3()),center:box.getCenter(new THREE.Vector3())};supply=new THREE.Mesh(appearanceGeometry(73,c.variant),material(c.color,c.variant));supply.scale.set(1.1,1.18,1.1);const knot=new THREE.Mesh(new THREE.ConeGeometry(.10,.18,14),material(c.color,c.variant));knot.rotation.z=Math.PI;knot.position.y=-1.10;supply.add(knot);supply.position.set(fit.center.x,fit.center.y,1);model.add(supply);turns=parts.length;parts.forEach(o=>{o.visible=false;o.scale.setScalar(.001)});face.visible=true;ui();}
function resize(){if(renderer)renderer.setSize(wrap.clientWidth,wrap.clientHeight,false)}
try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x080808,1);renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(35,1,.1,100);scene.add(new THREE.HemisphereLight(0xe5edff,0x342432,1.15));for(const [color,intensity,pos]of [[0xffffff,3.2,[-4,7,6]],[0xb6c9ff,2,[5,3,-3]],[0xffb8e8,1,[-5,0,-3]]]){const l=new THREE.DirectionalLight(color,intensity);l.position.set(...pos);scene.add(l)}
const envCanvas=document.createElement('canvas');envCanvas.width=1024;envCanvas.height=512;const ec=envCanvas.getContext('2d');ec.fillStyle='#15151a';ec.fillRect(0,0,1024,512);ec.fillStyle='#ffffff';ec.fillRect(70,50,105,270);ec.fillRect(590,65,130,230);ec.fillStyle='#b6b2c4';ec.fillRect(260,15,240,80);ec.fillStyle='#ede0ff';ec.fillRect(930,150,70,220);const env=new THREE.CanvasTexture(envCanvas);env.mapping=THREE.EquirectangularReflectionMapping;const pm=new THREE.PMREMGenerator(renderer);scene.environment=pm.fromEquirectangular(env).texture;env.dispose();pm.dispose();finale=createFinale(scene,reduced);requestMonster();resize();new ResizeObserver(resize).observe(wrap);animate();}catch(e){$('#error').hidden=false;console.error(e);ui()}

function animate(){requestAnimationFrame(animate);if(!renderer||!fit||document.hidden||$('#galleryDialog').open||$('#saveDialog').open)return;const c=characters[index],elapsed=clock.getElapsedTime(),p=step/turns;flash*=.88;const now=performance.now();let phase=action?Math.min(1,(now-action.start)/(Math.max(45,Math.min(130,3600/turns))*(now<boostUntil?.65:1))):0;if(action&&phase===1){step++;action=null;phase=0;flash=.5;if(step===turns)celebrate();ui();if(autoBuild&&step<turns){queued=Math.max(0,queued-1);beginTwist()}}
parts.forEach((o,i)=>{if(i<step){o.visible=true;o.scale.setScalar(1);o.position.set(0,0,0);o.rotation.set(0,0,0);}else if(i===step&&action){const f=THREE.MathUtils.smoothstep(phase,.40,1);o.visible=f>.001;o.scale.setScalar(.06+.94*f);o.position.set((1-f)*-.2,(1-f)*-.4,(1-f)*.25);o.rotation.z=(1-f)*-.28;}else{o.visible=false;o.scale.setScalar(.001)}});face.visible=true;
const target=step===0?1:Math.max(0,1-p*4.5),pulse=reduced?1:1+Math.sin(elapsed*2.2)*.025,squish=autoBuild?Math.sin(phase*Math.PI)*.13:0;supply.scale.lerp(new THREE.Vector3(1.1*target*pulse*(1+squish),1.18*target*pulse*(1-squish),1.1*target*pulse),.2);supply.visible=supply.scale.x>.015;supply.rotation.z=reduced?0:Math.sin(elapsed*1.3)*.045;supply.position.y=fit.center.y;
model.rotation.y=rotation+(reduced?0:Math.sin(elapsed*.4)*.065);model.rotation.x=tilt+flash*.08;model.rotation.z=0;model.position.x=0;model.position.y=reduced?0:Math.sin(elapsed*1.7)*.035;model.scale.setScalar(1+flash*.035);if(step===turns&&danceMode>=0&&!finale.active)applyDance(elapsed);
const w=wrap.clientWidth,h=wrap.clientHeight,bottomSpace=step===turns?155:100,usable=h-bottomSpace;renderer.setViewport(0,bottomSpace,w,usable);camera.aspect=w/usable;camera.updateProjectionMatrix();const size=fit.size,tan=Math.tan(THREE.MathUtils.degToRad(35/2)),visualWidth=THREE.MathUtils.lerp(2.8,size.x,p),visualHeight=THREE.MathUtils.lerp(2.8,size.y,p);const distance=Math.max(visualHeight/(2*tan),visualWidth/(2*tan*camera.aspect))*1.2+size.z*.27;const center=fit.center;camera.position.set(center.x,center.y+distance*.10/zoom,distance/zoom+center.z);camera.lookAt(center.x,center.y,center.z);finale?.update(parts);renderer.render(scene,camera);}
function ui(){const done=step===turns;$('#monsterTools').hidden=!done;$('#danceLabel').hidden=!done||danceMode<0;$('#danceLabel').textContent=danceMode<0?'':danceNames[danceMode];$('#stopDance').hidden=danceMode<0;$('#dance').classList.toggle('active',danceMode>=0);$('#dance').disabled=!!finale?.active;$('#hint').textContent=assignmentLoading?'Finding your monster…':step===0?'Tap to wake it up.':done?'':'Watch it come alive.';$('#hint').hidden=done;$('#again').hidden=!done;$('#finish').hidden=!done;$('#finish').disabled=!!finale?.active;$('#progress').hidden=done;$('#progress span').style.width=(turns?step/turns*100:0)+'%';$('#stepLabel').textContent='';canvas.setAttribute('aria-label',done?'Your monster. Drag to rotate.':'Tap the mystery balloon or press Enter to reveal your monster.');$('#tapTarget').setAttribute('aria-label',done?'Finished monster':'Build your monster');$('#tapTarget').setAttribute('aria-disabled',String(done));$('#announcement').textContent=done?'Your monster is ready.':step?'Your monster is coming alive.':'';}
function beginTwist(){action={start:performance.now()};if(performance.now()-lastSqueak>210){lastSqueak=performance.now();audio.twist(.20)}if(step%5===0)navigator.vibrate?.(8);}
function tap(){if(assignmentLoading||step>=turns||performance.now()-lastTap<80)return;lastTap=performance.now();flash=.3;if(autoBuild){boostUntil=performance.now()+700;return}autoBuild=true;beginTwist();$('#hint').textContent='Watch it come alive.';}
canvas.addEventListener('pointerdown',e=>{if(assignmentLoading)return;canvas.setPointerCapture(e.pointerId);touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(step===turns&&touches.size===2){const [a,b]=[...touches.values()];pinchState={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom};return}pointer={x:e.clientX,y:e.clientY,r:rotation,t:tilt};if(step<turns)tap()});
canvas.addEventListener('pointermove',e=>{if(touches.has(e.pointerId))touches.set(e.pointerId,{x:e.clientX,y:e.clientY});if(step===turns&&pinchState&&touches.size===2){const [a,b]=[...touches.values()];zoom=THREE.MathUtils.clamp(pinchState.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinchState.distance),.65,2.6);return}if(!pointer||step<turns)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;rotation=pointer.r+dx*.012;tilt=THREE.MathUtils.clamp(pointer.t+dy*.006,-.6,.6)});
for(const name of ['pointerup','pointercancel'])canvas.addEventListener(name,e=>{touches.delete(e.pointerId);if(touches.size<2)pinchState=null;pointer=null});window.addEventListener('blur',()=>{pointer=null;touches.clear();pinchState=null;queued=0});
canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=THREE.MathUtils.clamp(zoom*Math.exp(-e.deltaY*.0018),.65,2.6)},{passive:false});
$('#tapTarget').onclick=()=>tap();$('#again').onclick=()=>requestMonster();$('#sound').onclick=()=>{audio.setEnabled(!audio.enabled);$('#sound').setAttribute('aria-pressed',String(audio.enabled));$('#sound').setAttribute('aria-label',audio.enabled?'Mute sound':'Enable sound');$('#sound').textContent=audio.enabled?'♪':'♩';$('#sound').style.opacity=audio.enabled?1:.35;};

let previewRenderer,previewScene,previewCamera,previewRequest=0;
function initPreviews(){if(previewRenderer)return;previewRenderer=new THREE.WebGLRenderer({alpha:true,antialias:true});previewRenderer.setSize(220,220);previewRenderer.setClearColor(0x101010,1);previewRenderer.toneMapping=THREE.ACESFilmicToneMapping;previewRenderer.toneMappingExposure=1.08;previewScene=new THREE.Scene();previewScene.environment=scene.environment;previewScene.add(new THREE.HemisphereLight(0xe5edff,0x342432,1.15));const l=new THREE.DirectionalLight(0xffffff,3.2);l.position.set(-4,7,6);previewScene.add(l);previewCamera=new THREE.PerspectiveCamera(35,1,.1,100);}
function thumbnail(c){if(previewCache.has(c.id))return previewCache.get(c.id);initPreviews();previewMode=true;const b=makeCharacter(c);previewMode=false;b.group.rotation.y=c.angle;previewScene.add(b.group);const box=new THREE.Box3().setFromObject(b.group),sz=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),d=Math.max(sz.y,sz.x)/.63*1.17+sz.z*.25;previewCamera.position.set(center.x,center.y+d*.1,center.z+d);previewCamera.lookAt(center);previewRenderer.render(previewScene,previewCamera);const url=previewRenderer.domElement.toDataURL('image/png');previewCache.set(c.id,url);previewScene.remove(b.group);disposeModel(b.group);b.face.userData.resources.forEach(m=>m.dispose());return url;}
let galleryTab='catalog';
async function showGallery(){holding=false;clearTimeout(holdTimer);$('#galleryDialog').showModal();renderCatalog();}
async function renderCatalog(){const request=++previewRequest;galleryTab='catalog';$('#catalogTab').setAttribute('aria-selected','true');$('#peopleTab').setAttribute('aria-selected','false');$('#galleryGrid').replaceChildren();characters.forEach((c,i)=>{const card=document.createElement('article');card.className='monster-card';card.setAttribute('aria-label','Monster '+String(i+1).padStart(2,'0'));card.innerHTML='<img alt="" hidden><span>#'+String(i+1).padStart(2,'0')+'</span>';$('#galleryGrid').append(card)});const cards=[...$('#galleryGrid').children];for(let i=0;i<characters.length;i++){if(request!==previewRequest||!$('#galleryDialog').open)return;cards[i].querySelector('img').src=thumbnail(characters[i]);cards[i].querySelector('img').hidden=false;await new Promise(requestAnimationFrame)}}
async function showPeople(){++previewRequest;galleryTab='people';$('#catalogTab').setAttribute('aria-selected','false');$('#peopleTab').setAttribute('aria-selected','true');$('#galleryGrid').replaceChildren();try{const r=await fetch('/api/gallery'),data=await r.json();if(galleryTab!=='people')return;if(!data.items.length){$('#galleryGrid').innerHTML='<p class="empty">No portraits yet. Your monster can be the first.</p>';return}for(const item of data.items){const card=document.createElement('article');card.className='portrait-card';const im=new Image();im.src=item.image;im.alt='Monster made by '+item.name;const caption=document.createElement('b');caption.textContent=item.name;card.append(im,caption);$('#galleryGrid').append(card)}}catch{$('#galleryGrid').innerHTML='<p class="empty">The people’s gallery needs the local server.</p>'}}
$('#gallery').onclick=showGallery;$('#catalogTab').onclick=renderCatalog;$('#peopleTab').onclick=showPeople;document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#finish').onclick=()=>{if(finale?.active)return;$('#saveStatus').textContent='';$('#makerName').value='';$('#saveDialog').showModal();$('#makerName').focus()};
function makePhoto(name){const output=document.createElement('canvas');output.width=output.height=1200;const ctx=output.getContext('2d');ctx.fillStyle='#080808';ctx.fillRect(0,0,1200,1200);const oldAspect=camera.aspect,oldSize=renderer.getSize(new THREE.Vector2()),oldRatio=renderer.getPixelRatio();renderer.setPixelRatio(1);renderer.setSize(1200,1080,false);renderer.setViewport(0,0,1200,1080);camera.aspect=1200/1080;camera.updateProjectionMatrix();const oldPos=camera.position.clone(),oldRot=camera.quaternion.clone(),oldScale=model.scale.clone();model.scale.setScalar(1);const box=new THREE.Box3().setFromObject(model),sz=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),d=Math.max(sz.y,sz.x/camera.aspect)/.63*1.19+sz.z*.22;camera.position.set(center.x,center.y+d*.1,center.z+d);camera.lookAt(center);renderer.render(scene,camera);ctx.drawImage(canvas,0,0,1200,1080);camera.position.copy(oldPos);camera.quaternion.copy(oldRot);camera.aspect=oldAspect;camera.updateProjectionMatrix();model.scale.copy(oldScale);renderer.setPixelRatio(oldRatio);renderer.setSize(oldSize.x,oldSize.y,false);ctx.fillStyle='#f4f1e8';ctx.textAlign='center';ctx.font='bold 38px Helvetica, Arial, sans-serif';while(ctx.measureText(name).width>1060){const size=parseInt(ctx.font.match(/(\d+)px/)[1])-1;ctx.font='bold '+size+'px Helvetica, Arial, sans-serif'}ctx.fillText(name,600,1135);return output.toDataURL('image/png')}
function downloadPhoto(image,name){const link=document.createElement('a');link.href=image;link.download='Monster-'+name.replace(/[^a-zA-Z0-9_-]/g,'-').slice(0,40)+'.png';link.click()}
$('#saveForm').onsubmit=async e=>{e.preventDefault();const name=$('#makerName').value.trim();if(!name){$('#makerName').focus();return}const button=$('#savePhoto');button.disabled=true;$('#saveStatus').textContent='Taking your portrait…';try{await new Promise(requestAnimationFrame);const image=makePhoto(name);lastSaved={image,name};const response=await fetch('/api/snapshot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,characterId:characters[index].id,image})});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not save.');$('#saveStatus').textContent='Saved to Desktop. Added to Everyone’s monsters.';$('#fallbackDownload').hidden=true;}catch(err){$('#saveStatus').textContent=(err.message||'Desktop saving is unavailable.')+' You can download the PNG below.';$('#fallbackDownload').hidden=false;}finally{button.disabled=false}};
$('#fallbackDownload').onclick=()=>{if(lastSaved)downloadPhoto(lastSaved.image,lastSaved.name)};

async function requestMonster(){if(assignmentLoading)return;assignmentLoading=true;$('#hint').textContent='Finding your monster…';makerId=crypto.randomUUID();try{const r=await fetch('/api/assignment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({makerId})});if(!r.ok)throw Error('Assignment unavailable');const data=await r.json(),n=characters.findIndex(c=>c.id===data.characterId);if(n<0)throw Error('Unknown design');surprise(n);}catch{let used=[];try{used=JSON.parse(localStorage.getItem('monster-assignment-fallback')||'[]')}catch{}let pool=characters.map((c,i)=>i).filter(i=>!used.includes(characters[i].id));if(!pool.length){used=[];pool=characters.map((c,i)=>i)}const n=pool[Math.floor(Math.random()*pool.length)];used.push(characters[n].id);try{localStorage.setItem('monster-assignment-fallback',JSON.stringify(used))}catch{}surprise(n);}finally{assignmentLoading=false;ui();}}
function celebrate(){autoBuild=false;queued=0;holding=false;finale.start(fit.center.clone(),'#9bff43',parts.length);audio.pop();$('#blast').classList.remove('burst');void $('#blast').offsetWidth;$('#blast').classList.add('burst');$('.playground').classList.remove('shake');void $('.playground').offsetWidth;$('.playground').classList.add('shake');setTimeout(()=>{if(step===turns)$('#finish').disabled=false;$('#dance').disabled=false},1500);}

$('#zoomIn').onclick=()=>zoom=Math.min(2.6,zoom*1.2);$('#zoomOut').onclick=()=>zoom=Math.max(.65,zoom/1.2);
$('#dance').onclick=()=>{if(step!==turns||finale.active)return;danceMode=danceMode<0?characters[index].variant%danceNames.length:(danceMode+1)%danceNames.length;danceStarted=clock.getElapsedTime();ui()};$('#stopDance').onclick=()=>{danceMode=-1;ui()};
function applyDance(elapsed){const t=(elapsed-danceStarted)*5.5*(.8+(characters[index].variant%7)*.06),b=Math.sin(t),c=Math.cos(t),strength=reduced?.25:1;
 if(danceMode===0){model.position.y+=Math.abs(b)*.22*strength;model.scale.set(1+Math.abs(b)*.055*strength,1-Math.abs(b)*.07*strength,1+Math.abs(b)*.04*strength);model.rotation.z=b*.06*strength}
 if(danceMode===1){model.position.x=Math.sin(t*.5)*.22*strength;model.position.y+=Math.abs(Math.sin(t))*.1*strength;model.rotation.y+=Math.sin(t*.5)*.23*strength;model.rotation.z=Math.sin(t*.5)*.06*strength}
 if(danceMode===2){model.rotation.y+=b*.55*strength;model.rotation.z=c*.09*strength;model.position.y+=Math.abs(Math.sin(t*.5))*.08*strength}
 if(danceMode===3){model.rotation.y+=Math.round(b*2)*.16*strength;model.rotation.z=Math.round(Math.sin(t*.5)*2)*.035*strength;model.position.x=Math.round(c)*.08*strength}
 if(danceMode===4){model.rotation.x+=b*.22*strength;model.position.y+=c*.07*strength;model.rotation.z=Math.sin(t*.5)*.035*strength}
 if(danceMode===5){model.rotation.z=b*.14*strength;model.rotation.y+=Math.sin(t*1.4)*.28*strength;model.position.y+=Math.abs(c)*.12*strength}
 if(danceMode===6){const pump=Math.sin(t*1.65);model.rotation.y+=Math.PI*.78;model.rotation.x+=.19*strength;model.position.y-=.16*strength;model.position.y+=pump*.055*strength;model.rotation.z=Math.sin(t*.8)*.035*strength;model.scale.set(1+.025*pump*strength,1-.06*strength,1+.04*pump*strength)}
 parts.forEach((part,i)=>{const a=part.userData.anchor;if(!a)return;const low=a.y<fit.center.y-.3,high=a.y>fit.center.y+.5,side=a.x>=fit.center.x?1:-1;const swing=Math.sin(t+(i%2)*Math.PI);if(danceMode===6){const pump=Math.sin(t*1.65),hip=a.y<fit.center.y+.1&&!low;if(low){part.rotation.z=side*(.13+.045*pump)*strength;part.rotation.x=-.10*strength;part.position.y=-.035*strength}else if(hip){part.rotation.x=pump*.14*strength;part.position.z=pump*.10*strength;part.position.y=pump*.035*strength}else if(high){part.rotation.x=-pump*.035*strength}}else if(danceMode===1&&low){part.rotation.x=swing*.10*strength;part.position.y=Math.max(0,swing)*.06*strength}else if(danceMode===3){part.rotation.z=Math.round(Math.sin(t+i*.7))*side*.05*strength}else if(danceMode===4&&high){part.rotation.x=b*.10*strength}else if(danceMode===5){part.rotation.z=Math.sin(t+i*.4)*.06*strength}else if(low)part.rotation.z=swing*.045*strength;const rotated=a.clone().applyQuaternion(part.quaternion);part.position.add(a.clone().sub(rotated));});
}
